+//! Experimental explicit immutable wind terms; not a global or benchmark-specific cache.
+use super::{FuelbedIntermediates, WindCoefficients};
+#[derive(Clone,Copy,Debug,PartialEq)]
+pub(crate) struct PreparedWind {
+    pub coefficients: WindCoefficients,
+    sigma: f64,
+    packing: f64,
+    positive: f64,
+    negative: f64,
+}
+impl PreparedWind {
+    pub fn new(bed:&FuelbedIntermediates)->Self {
+        let c=super::calculate_surface_wind_coefficients(bed.sigma);
+        let packing=if bed.relative_packing_ratio>1e-7 {bed.relative_packing_ratio} else {1.};
+        Self {coefficients:c,sigma:bed.sigma,packing:bed.relative_packing_ratio,
+            positive:packing.powf(c.wind_e), negative:packing.powf(-c.wind_e)}
+    }
+    pub fn matches(&self, bed:&FuelbedIntermediates)->bool {
+        self.sigma.to_bits()==bed.sigma.to_bits() && self.packing.to_bits()==bed.relative_packing_ratio.to_bits()
+    }
+    pub fn wind_phi(&self,mid:f64)->f64 {
+        if self.sigma>1e-7 && mid>1e-7 {mid.powf(self.coefficients.wind_b)*self.coefficients.wind_c*self.negative} else {0.}
+    }
+    pub fn effective(&self, spread:f64, r0:f64)->f64 {
+        let c=self.coefficients;
+        let r0_safe=if r0>1e-7 {r0} else {1.};
+        let phi=if r0>1e-7 {spread/r0_safe-1.} else {0.};
+        let wc=if c.wind_c>1e-7 {c.wind_c} else {1.};
+        let wb=if c.wind_b>1e-7 {c.wind_b} else {1.};
+        let fpm=if phi>0. && c.wind_b>1e-7 && c.wind_c>1e-7 && self.packing>1e-7 {
+            ((phi*self.positive)/wc).powf(1./wb)
+        } else {0.};
+        fpm*0.01136363636
+    }
+}
